<?php require_once 'config.php'; if(logged()) redirect('index.php'); $pageTitle='Criar conta'; $errors=[]; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$nome=trim($_POST['nome']??'');$email=trim(strtolower($_POST['email']??''));$senha=$_POST['senha']??'';$conf=$_POST['confirmar']??'';if($nome==='')$errors[]='Informe seu nome completo.';if(!valid_email($email))$errors[]='Informe um e-mail válido.';if(strlen($senha)<6)$errors[]='A senha deve possuir pelo menos seis caracteres.';if($senha!==$conf)$errors[]='A confirmação de senha não confere.';if(!$errors){$s=db()->prepare('SELECT id FROM usuarios WHERE email=?');$s->execute([$email]);if($s->fetch())$errors[]='Este e-mail já está cadastrado.';}if(!$errors){$s=db()->prepare("INSERT INTO usuarios(nome,email,senha,tipo) VALUES(?,?,?,'usuario')");$s->execute([$nome,$email,password_hash($senha,PASSWORD_DEFAULT)]);flash('Conta criada com sucesso! Faça login para continuar.');redirect('login.php');}} require 'includes/header.php'; ?>
<div class="form-wrap"><form class="form-card" method="post"><h1>Crie sua conta</h1><p>Cadastre-se para reservar sua próxima corrida.</p><?php foreach($errors as $er): ?><div class="alert danger"><?= e($er) ?></div><?php endforeach; ?><input type="hidden" name="csrf" value="<?= csrf() ?>"><div class="field"><label>Nome completo</label><input name="nome" value="<?= e($_POST['nome']??'') ?>" required></div><div class="field"><label>E-mail</label><input type="email" name="email" value="<?= e($_POST['email']??'') ?>" required></div><div class="field"><label>Senha</label><input type="password" name="senha" minlength="6" required></div><div class="field"><label>Confirmar senha</label><input type="password" name="confirmar" minlength="6" required></div><button class="btn">CRIAR CONTA</button><div class="form-foot">Já possui uma conta? <a href="login.php">Entrar</a></div></form></div><?php require 'includes/footer.php'; ?>
